-- Atomic source-based intake for four exact Honda catalogue identities.
-- Factory source captures are draft only, not source audit or publication.
DO $$
DECLARE matched integer; inserted integer; released_before integer; released_after integer;
BEGIN
 SELECT count(*) INTO released_before FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,make,name) AS (VALUES
 (854,'Honda','CB400 Super Four'),
  (837,'Honda','CB1100'),
  (798,'Honda','CB1300'),
  (444,'Honda','CB500F')
 )
 SELECT count(*) INTO matched FROM expected e
 JOIN public.motorcycle_catalog_models m ON m.id=e.id AND m.manufacturer=e.make AND m.model=e.name
 WHERE NOT EXISTS (SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s
 WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS (SELECT 1 FROM public.motorcycle_catalog_model_aliases a
 WHERE a.alias_model_id=e.id AND a.review_status<>'approved');
 IF matched<>4 THEN RAISE EXCEPTION 'Honda source capture aborted: ID/staging mismatch (%)',matched; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.section_number,v.section_title,v.content,'draft',
 'honda_factory_cb_history:'||v.source_url,NULL
 FROM (VALUES
 (854,1,'Model introduction','{"summary":"The Honda CB400 Super Four was a Japanese-market naked roadster shaped by Honda''s Project BIG-1 concept.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/1992_2/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/1992_2/'),
  (854,7,'Documented model history','{"summary":"Honda''s official CB history records its Japanese launch in April 1992 and production continuing until October 2022.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/1992_2/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/1992_2/'),
  (854,12,'Engineering and generation history','{"summary":"Honda documents the arrival of HYPER VTEC in 1999 and subsequent revisions in 2002, 2003 and 2007. The operating characteristics and valve switching thresholds varied by generation.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/1992_2/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/1992_2/'),
  (837,1,'Model introduction','{"summary":"Honda''s CB1100 brought a traditional air-cooled inline-four roadster layout into the modern CB range, emphasising classic appearance and approachable handling.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/2010/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/2010/'),
  (837,7,'Documented model history','{"summary":"Honda records the Japan-market CB1100''s 2010 debut, its European-market launch in 2013 and the end of the production run in 2021.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/2010/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/2010/'),
  (837,12,'Engineering and generation history','{"summary":"Honda documents a steel double-cradle frame, 18-inch wheels and its air-cooled four-cylinder architecture for the original generation; later editions need individual specification review.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/2010/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/2010/'),
  (798,1,'Model introduction','{"summary":"Honda''s CB1300 Super Four grew out of the manufacturer''s large-capacity naked-roadster Project BIG-1 family.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/1998/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/1998/'),
  (798,7,'Documented model history','{"summary":"Honda''s historical account records a CB1300 Super Four reference model at the 1997 Tokyo Motor Show, followed by its Japanese launch in March 1998.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/1998/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/1998/'),
  (798,12,'Engineering and generation history','{"summary":"Honda describes the early CB1300 Super Four as combining a large displacement engine with a chassis designed for accessible handling. The later 2003 generation requires a separate source review.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/1998/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/1998/'),
  (444,1,'Model introduction','{"summary":"Honda''s CB500F was designed as a modern naked mid-capacity road motorcycle with approachable everyday usability.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/2013/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/2013/'),
  (444,7,'Documented model history','{"summary":"Honda unveiled the CB500F at EICMA in November 2012 as part of its new 2013 European mid-capacity range.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/2013/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/2013/'),
  (444,12,'Engineering and generation history','{"summary":"Honda documents a liquid-cooled DOHC four-stroke parallel-twin for the original CB500F generation; Japanese CB400F specifications must not be assigned to the CB500F.","source_name":"Honda Global CB Stories","source_url":"https://global.honda/en/CB/history/stories/2013/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private original-source summary. Confirm historical market, year, variant, and rights before any public approval."}'::jsonb,'https://global.honda/en/CB/history/stories/2013/')
 ) AS v(model_id,section_number,section_title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>12 THEN RAISE EXCEPTION 'Honda source capture expected 12, inserted %',inserted; END IF;
 SELECT count(*) INTO released_after FROM public.motorcycle_universal_published_sections_v1;
 IF released_after<>released_before THEN RAISE EXCEPTION 'Honda source capture changed publication projection'; END IF;
END $$;
